<?php
 define( 'ABSPATH', __DIR__ . '/' ); class WP_Error { private $code; public function __construct( $code, $message = '' ) { $this->code = $code; } public function get_error_code() { return $this->code; } } function is_wp_error( $value ) { return $value instanceof WP_Error; } function absint( $value ) { return abs( (int) $value ); } function sanitize_key( $value ) { return strtolower( preg_replace( '/[^a-z0-9_\-]/', '', (string) $value ) ); } function sanitize_text_field( $value ) { return trim( strip_tags( (string) $value ) ); } function sanitize_textarea_field( $value ) { return trim( strip_tags( (string) $value ) ); } function esc_url_raw( $value ) { return filter_var( trim( (string) $value ), FILTER_VALIDATE_URL ) ? trim( (string) $value ) : ''; } function current_time( $type, $gmt = false ) { return '2026-09-12 10:00:00'; } class UPK_Repository { const SUBJECT_PRODUCT = 'product'; public static function lifecycle_statuses() { return array( 'ACTIVE', 'TEMPORARILY_UNAVAILABLE', 'DISCONTINUED', 'UNKNOWN' ); } public static function fact_statuses() { return array( 'VERIFIED', 'NOT_IN_SOURCE', 'SOURCE_CONFLICT', 'CONFIGURATION_DEPENDENT' ); } } class Import_Fake_WPDB { public $prefix = 'wp_'; public $queries = array(); public $last_update = null; public function query( $sql ) { $this->queries[] = $sql; return true; } public function update( $table, $data, $where, $formats, $where_formats ) { $this->last_update = array( 'table' => $table, 'data' => $data, 'where' => $where ); return 1; } } class Import_Fake_Knowledge { public $products = array(); public $facts = array(); private $next_product = 1; private $next_fact = 1; public function create_product( array $data ) { $id = $this->next_product++; $data['id'] = $id; $data['model_family'] = isset( $data['model_family'] ) ? $data['model_family'] : ''; $data['successor_product_id'] = null; $data['identifiers'] = array(); $data['facts'] = array(); $data['variants'] = array(); $this->products[ $id ] = $data; return $id; } public function get_product_bundle( $id ) { if ( ! isset( $this->products[ $id ] ) ) { return new WP_Error( 'UPK_PRODUCT_NOT_FOUND', 'missing' ); } $bundle = $this->products[ $id ]; $bundle['facts'] = array_values( isset( $this->facts[ $id ] ) ? $this->facts[ $id ] : array() ); return $bundle; } public function add_fact( $subject_type, $subject_id, array $data ) { if ( ! isset( $this->products[ $subject_id ] ) ) { return new WP_Error( 'UPK_PRODUCT_NOT_FOUND', 'missing' ); } $key = $data['fact_key'] . "\n" . $data['source_url']; if ( isset( $this->facts[ $subject_id ][ $key ] ) ) { $id = $this->facts[ $subject_id ][ $key ]['_id']; } else { $id = $this->next_fact++; } $row = $data; $row['_id'] = $id; $this->facts[ $subject_id ][ $key ] = $row; return $id; } public function fact_row_count() { $count = 0; foreach ( $this->facts as $rows ) { $count += count( $rows ); } return $count; } } class Import_Fake_Maintenance { private $knowledge; public function __construct( $knowledge ) { $this->knowledge = $knowledge; } public function find_product_id_by_identity( array $data ) { $matches = array(); foreach ( $this->knowledge->products as $id => $p ) { if ( (string) $p['manufacturer'] === (string) $data['manufacturer'] && (string) $p['model_name'] === (string) $data['model_name'] && (string) $p['product_group_key'] === (string) $data['product_group_key'] && (string) ( $p['generation'] ?? '' ) === (string) ( $data['generation'] ?? '' ) ) { $matches[] = $id; } } if ( count( $matches ) > 1 ) { return new WP_Error( 'UPK_DUPLICATE_PRODUCT_IDENTITY', 'duplicate' ); } return empty( $matches ) ? 0 : (int) $matches[0]; } public function update_product( $id, array $data ) { if ( ! isset( $this->knowledge->products[ $id ] ) ) { return new WP_Error( 'UPK_PRODUCT_NOT_FOUND', 'missing' ); } foreach ( $data as $key => $value ) { $this->knowledge->products[ $id ][ $key ] = $value; } return $id; } } class Import_Fake_Comparisons { public $comparisons = array(); private $next_id = 1; private $knowledge; public function __construct( $knowledge ) { $this->knowledge = $knowledge; } public function find_comparison_id_by_key( $key ) { foreach ( $this->comparisons as $id => $c ) { if ( $c['comparison_key'] === $key ) { return $id; } } return 0; } public function create_comparison( array $data ) { $canonical = $data['subject_ids']; sort( $canonical, SORT_NUMERIC ); $set = $data['comparison_type'] . ':' . implode( ',', $canonical ); foreach ( $this->comparisons as $c ) { $other = $c['subject_ids']; sort( $other, SORT_NUMERIC ); if ( $c['comparison_type'] . ':' . implode( ',', $other ) === $set ) { return new WP_Error( 'UPC_DUPLICATE_COMPARISON', 'duplicate' ); } } $id = $this->next_id++; $row = $data; $row['id'] = $id; $row['comparison_uid'] = 'UPC-' . str_pad( (string) $id, 6, '0', STR_PAD_LEFT ); $first_product = $this->knowledge->get_product_bundle( (int) $data['subject_ids'][0] ); $row['product_group_key'] = is_wp_error( $first_product ) ? '' : (string) $first_product['product_group_key']; $row['features'] = array(); $this->comparisons[ $id ] = $row; return $id; } public function set_features( $id, array $features, $manage_transaction = true ) { if ( ! isset( $this->comparisons[ $id ] ) ) { return new WP_Error( 'UPC_COMPARISON_NOT_FOUND', 'missing' ); } $normalized = array(); foreach ( array_values( $features ) as $i => $f ) { $f['position'] = $i + 1; $normalized[] = $f; } $this->comparisons[ $id ]['features'] = $normalized; return count( $normalized ); } public function get_comparison_bundle( $id ) { if ( ! isset( $this->comparisons[ $id ] ) ) { return new WP_Error( 'UPC_COMPARISON_NOT_FOUND', 'missing' ); } $c = $this->comparisons[ $id ]; $items = array(); foreach ( $c['subject_ids'] as $i => $sid ) { $items[] = array( 'subject_id' => $sid, 'position' => $i + 1 ); } return array( 'id' => $id, 'comparison_type' => $c['comparison_type'], 'comparison_mode' => $c['comparison_mode'], 'product_group_key' => $c['product_group_key'], 'working_title' => $c['working_title'], 'comparability_note' => $c['comparability_note'], 'items' => $items, 'features' => $c['features'], ); } public function bind_comparison_mode_if_empty( $id, $mode ) { if ( ! isset( $this->comparisons[ $id ] ) ) { return new WP_Error( 'UPC_COMPARISON_NOT_FOUND', 'missing' ); } $current = (string) $this->comparisons[ $id ]['comparison_mode']; if ( '' === $current ) { $this->comparisons[ $id ]['comparison_mode'] = $mode; return true; } return $current === $mode ? true : new WP_Error( 'UPC_COMPARISON_MODE_CONFLICT', 'conflict' ); } public function comparison_count() { return count( $this->comparisons ); } } class Import_Fake_Feature_Catalog { private $map = array(); public function __construct( $path ) { $data = json_decode( file_get_contents( $path ), true ); foreach ( $data['features'] as $row ) { $this->map[ $row['label'] ] = $row['fact_key']; } } public function resolve( $label ) { return isset( $this->map[ $label ] ) ? $this->map[ $label ] : new WP_Error( 'UPC_FEATURE_LABEL_UNKNOWN', 'unknown' ); } } function import_assert( $condition, $label ) { if ( ! $condition ) { fwrite( STDERR, "FAIL: {$label}\n" ); exit( 1 ); } fwrite( STDOUT, "PASS: {$label}\n" ); } require_once dirname( __DIR__ ) . '/src/class-upc-research-importer.php'; $config_dir = dirname( __DIR__ ) . '/config/pferde-atelier'; $plan = UPC_Research_Importer::load_bound_plan_from_directory( $config_dir, 'pferde-atelier' ); import_assert( ! is_wp_error( $plan ), 'bound gzip plan loads with both hashes' ); import_assert( 102 === (int) $plan['counts']['products'], 'bound plan has 102 products' ); import_assert( 1330 === (int) $plan['counts']['facts'], 'bound plan has 1330 facts' ); import_assert( 68 === (int) $plan['counts']['comparisons'], 'bound plan has 68 comparisons' ); import_assert( 1908 === (int) $plan['counts']['matrix_cells'], 'bound plan reconstructs 1908 matrix cells' ); $wpdb = new Import_Fake_WPDB(); $knowledge = new Import_Fake_Knowledge(); $maintenance = new Import_Fake_Maintenance( $knowledge ); $comparisons = new Import_Fake_Comparisons( $knowledge ); $catalog = new Import_Fake_Feature_Catalog( $config_dir . '/feature-key-catalog.json' ); $importer = new UPC_Research_Importer( $wpdb, $knowledge, $maintenance, $comparisons, $catalog ); $result = $importer->import_plan( $plan ); import_assert( ! is_wp_error( $result ) && 'RESEARCH_IMPORT_PASS' === $result['status'], 'full 68 dossier first import passes' ); import_assert( 102 === $result['products_created'] && 0 === $result['products_reused'], 'first import creates exactly 102 products' ); import_assert( 1330 === $knowledge->fact_row_count(), 'first import stores exactly 1330 source-bound facts' ); import_assert( 68 === $comparisons->comparison_count(), 'first import creates exactly 68 comparisons' ); import_assert( 68 === $result['comparisons_created'] && 0 === $result['comparisons_reused'], 'first import comparison counters exact' ); import_assert( 'COMMIT' === end( $wpdb->queries ), 'first import commits atomically' ); $result2 = $importer->import_plan( $plan ); import_assert( ! is_wp_error( $result2 ) && 'RESEARCH_IMPORT_PASS' === $result2['status'], 'second identical import passes' ); import_assert( 0 === $result2['products_created'] && 102 === $result2['products_reused'], 'second import reuses all products' ); import_assert( 1330 === $knowledge->fact_row_count(), 'second import creates zero fact duplicates' ); import_assert( 68 === $comparisons->comparison_count(), 'second import creates zero comparison duplicates' ); import_assert( 0 === $result2['comparisons_created'] && 68 === $result2['comparisons_reused'], 'second import reuses all comparisons' ); import_assert( 0 === $result2['fact_writes'], 'second identical import performs zero fact rewrites' ); $first_product_id = array_key_first( $knowledge->products ); $first_fact_key = array_key_first( $knowledge->facts[ $first_product_id ] ); $knowledge->products[ $first_product_id ]['last_verified_at'] = '2027-01-01 00:00:00'; $knowledge->products[ $first_product_id ]['manufacturer_product_url'] = 'https://newer.example/product'; $knowledge->facts[ $first_product_id ][ $first_fact_key ]['verified_at'] = '2027-01-01 00:00:00'; $knowledge->facts[ $first_product_id ][ $first_fact_key ]['fact_value'] = 'NEWER LIVE VALUE'; $result_newer = $importer->import_plan( $plan ); import_assert( ! is_wp_error( $result_newer ) && 'RESEARCH_IMPORT_PASS' === $result_newer['status'], 'old bootstrap can replay without regressing newer maintenance state' ); import_assert( '2027-01-01 00:00:00' === $knowledge->products[ $first_product_id ]['last_verified_at'], 'newer product verification date preserved' ); import_assert( 'https://newer.example/product' === $knowledge->products[ $first_product_id ]['manufacturer_product_url'], 'newer product source URL preserved' ); import_assert( '2027-01-01 00:00:00' === $knowledge->facts[ $first_product_id ][ $first_fact_key ]['verified_at'], 'newer fact verification date preserved' ); import_assert( 'NEWER LIVE VALUE' === $knowledge->facts[ $first_product_id ][ $first_fact_key ]['fact_value'], 'newer fact value preserved' ); import_assert( 1 === $result_newer['facts_preserved_newer'], 'newer source-bound fact counted as preserved' ); $first_id = array_key_first( $comparisons->comparisons ); $comparisons->comparisons[ $first_id ]['comparison_mode'] = ''; $result3 = $importer->import_plan( $plan ); import_assert( ! is_wp_error( $result3 ), 'legacy empty comparison mode can be bound safely' ); import_assert( 'wp_upc_comparisons' === $wpdb->last_update['table'] && '' !== $wpdb->last_update['data']['comparison_mode'], 'legacy comparison mode bind is a single guarded table update' ); $bad_comparisons = clone $comparisons; $bad_id = array_key_first( $bad_comparisons->comparisons ); $bad_comparisons->comparisons[ $bad_id ]['subject_ids'] = array_reverse( $bad_comparisons->comparisons[ $bad_id ]['subject_ids'] ); $bad_wpdb = new Import_Fake_WPDB(); $bad_importer = new UPC_Research_Importer( $bad_wpdb, $knowledge, $maintenance, $bad_comparisons, $catalog ); $bad = $bad_importer->import_plan( $plan ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_EXISTING_COMPARISON_ITEMS_MISMATCH' === $bad->get_error_code(), 'conflicting existing comparison order blocks' ); import_assert( 'ROLLBACK' === end( $bad_wpdb->queries ), 'conflicting existing state rolls back' ); $bad_plan = $plan; $bad_plan['sources'][0]['manufacturer'] = 'Wrong Manufacturer'; $pre_wpdb = new Import_Fake_WPDB(); $pre_importer = new UPC_Research_Importer( $pre_wpdb, new Import_Fake_Knowledge(), new Import_Fake_Maintenance( new Import_Fake_Knowledge() ), new Import_Fake_Comparisons( new Import_Fake_Knowledge() ), $catalog ); $bad = $pre_importer->import_plan( $bad_plan ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_PRODUCT_INVALID' === $bad->get_error_code(), 'source manufacturer mismatch blocked before writes' ); import_assert( empty( $pre_wpdb->queries ), 'invalid plan starts no transaction' ); $bad_plan = $plan; $bad_plan['comparisons'][0]['features'][0]['label'] = 'Ungebundenes Fantasiemerkmal'; $bad = $importer->import_plan( $bad_plan ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_FEATURE_INVALID' === $bad->get_error_code(), 'unknown feature label blocked fail closed' ); $bad_plan = $plan; $bad_plan['counts']['facts'] = 1329; $bad = $importer->import_plan( $bad_plan ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_COUNT_MISMATCH' === $bad->get_error_code(), 'count tampering blocked' ); $conflict_product_id = array_keys( $knowledge->products )[1]; $conflict_fact_key = array_key_first( $knowledge->facts[ $conflict_product_id ] ); $knowledge->facts[ $conflict_product_id ][ $conflict_fact_key ]['fact_value'] = 'AMBIGUOUS SAME-TIME VALUE'; $conflict_wpdb = new Import_Fake_WPDB(); $conflict_importer = new UPC_Research_Importer( $conflict_wpdb, $knowledge, $maintenance, $comparisons, $catalog ); $bad = $conflict_importer->import_plan( $plan ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_EXISTING_FACT_CONFLICT' === $bad->get_error_code(), 'same-time conflicting source-bound fact blocked' ); import_assert( 'ROLLBACK' === end( $conflict_wpdb->queries ), 'same-time fact conflict rolls back' ); $tmp = sys_get_temp_dir() . '/upc-research-import-' . uniqid(); mkdir( $tmp ); $manifest = json_decode( file_get_contents( $config_dir . '/project-manifest.json' ), true ); foreach ( $manifest['research_import']['parts'] as $part ) { copy( $config_dir . '/' . $part, $tmp . '/' . $part ); } $manifest['research_import']['sha256'] = str_repeat( '0', 64 ); file_put_contents( $tmp . '/project-manifest.json', json_encode( $manifest ) ); $bad = UPC_Research_Importer::load_bound_plan_from_directory( $tmp, 'pferde-atelier' ); import_assert( is_wp_error( $bad ) && 'UPC_RESEARCH_PLAN_HASH_MISMATCH' === $bad->get_error_code(), 'compressed plan hash tampering blocked' ); foreach ( $manifest['research_import']['parts'] as $part ) { unlink( $tmp . '/' . $part ); } unlink( $tmp . '/project-manifest.json' ); rmdir( $tmp ); fwrite( STDOUT, "UPC_RESEARCH_IMPORTER_68_GESAMT_PASS\n" ); 